package nl.smartstreamlabs.sbwdroneconfig;
import java.util.*;
import java.util.concurrent.atomic.AtomicLong;
public final class DwfCoreCheck{
 static int checks;static void check(boolean b,String s){if(!b)throw new AssertionError(s);checks++;}
 public static void main(String[]args)throws Exception{
  var a=new DwfBulkStore<String>(64_000_000,65536);check(a.insert("iron",Long.MAX_VALUE,false)==64_000_000,"capacity clips before addition");check(a.size()==1,"64 million items use one entry");check(a.total()==64_000_000,"exact total");check(a.insert("gold",1,false)==0,"full storage");check(a.extract("iron",100,true)==100&&a.total()==64_000_000,"simulate extract is read-only");a.extract("iron",Long.MAX_VALUE,false);check(a.size()==0&&a.total()==0,"empty variant removed");
  var v=new DwfBulkStore<String>(1000,2);v.insert("battery:dataA",1,false);v.insert("battery:dataB",1,false);check(v.insert("battery:dataC",1,true)==0,"variant cap");check(v.size()==2,"identities stay separate");long rev=v.revision();v.insert("battery:dataA",100,true);check(v.revision()==rev,"simulate insert is read-only");
  var large=new DwfBulkStore<String>(Long.MAX_VALUE,10);large.insert("x",Long.MAX_VALUE,false);check(large.insert("x",1,false)==0&&large.total()==Long.MAX_VALUE,"no long overflow");
  a.insert("iron",4,false);var out=new DwfBulkStore<String>(1,1);out.insert("occupied",1,false);check(!DwfBulkStore.produce(a,out,Map.of("iron",4L),"drone",1)&&a.count("iron")==4,"full output never consumes");out.extract("occupied",1,false);check(!DwfBulkStore.produce(a,out,Map.of("iron",5L),"drone",1)&&out.total()==0,"short ingredient never produces");check(DwfBulkStore.produce(a,out,Map.of("iron",4L),"drone",1)&&a.total()==0&&out.count("drone")==1,"atomic craft conservation");
  var snap=v.snapshot();check(snap.next(1).size()==1&&!snap.done(),"bounded snapshot");v.insert("battery:dataA",1,false);check(!snap.valid(),"snapshot reports older revision");check(snap.next(1).equals(List.of(new DwfBulkStore.Entry<>("battery:dataB",1L))),"frozen snapshot remains consistent during mutation");
  v.extract("battery:dataB",1,false);v.insert("battery:dataB",3,false);var deltas=v.takeChanges(1);check(deltas.size()==1,"bounded listener drain");check(v.takeChanges(10).equals(List.of(new DwfBulkStore.Entry<>("battery:dataB",3L))),"notifications coalesced");
  final boolean[]unsafe={false};Thread t=new Thread(()->{try{v.count("battery:dataA");}catch(IllegalStateException e){unsafe[0]=true;}});t.start();t.join();check(unsafe[0],"reject worker inventory access");
  var clock=new AtomicLong();var scheduler=new DwfWorkBudget(clock::get);int[]called=new int[100];DwfWorkBudget.Job[]jobs=new DwfWorkBudget.Job[100];for(int i=0;i<100;i++){final int n=i;jobs[i]=new DwfWorkBudget.Job(){public DwfWorkBudget.Kind kind(){return DwfWorkBudget.Kind.COMPLETION;}public boolean step(){called[n]++;clock.addAndGet(10);return true;}};scheduler.add(jobs[i]);scheduler.add(jobs[i]);}check(scheduler.size()==100,"no duplicate registration");for(int i=0;i<10;i++){var m=scheduler.tick(10,1000,Map.of(),false);check(m.operations()==10,"one shared operations budget");}check(Arrays.stream(called).allMatch(n->n==1),"round-robin fairness across 100 machines");check(scheduler.tick(100,1000,Map.of(DwfWorkBudget.Kind.COMPLETION,3),false).operations()==3,"global completion cap");scheduler.remove(jobs[0]);check(scheduler.size()==99,"unload unregisters");scheduler.clear();check(scheduler.size()==0,"server stop cleanup");
  var pi=new DwfBulkStore<String>(1000,10);var po=new DwfBulkStore<String>(1000,10);var engine=new DwfProduction<String>();var recipe=new DwfProduction.Recipe<>("real",Map.of("metal",2L),"product",1,100);engine.select(recipe);engine.start(2,false);
  engine.visit(0,pi,po,true);check(engine.state()==DwfProduction.State.MISSING_INPUT,"empty input blocks production");pi.insert("metal",4,false);engine.visit(10,pi,po,true);engine.visit(60,pi,po,true);check(engine.progress()==50&&pi.total()==4,"progress does not consume early");engine.pause();engine.visit(1000,pi,po,true);check(engine.progress()==50,"pause freezes progress");engine.resume();engine.visit(1100,pi,po,true);engine.visit(1150,pi,po,true);check(po.count("product")==1&&pi.count("metal")==2,"resume completes atomically");
  engine.visit(1200,pi,po,true);var saved=engine.save();engine.unload();engine.restore(saved,recipe);engine.visit(20000,pi,po,true);check(engine.progress()==saved.progress(),"reload does not fabricate offline progress");engine.visit(20100,pi,po,false);check(po.count("product")==1,"completion budget prevents commit");engine.visit(20101,pi,po,true);check(po.count("product")==2&&engine.state()==DwfProduction.State.IDLE,"fixed quantity stops exactly");
  engine.select(recipe);engine.start(1,true);pi.insert("metal",20,false);engine.visit(30000,pi,po,true);engine.visit(999999,pi,po,true);check(po.count("product")==3,"no catch-up burst");engine.select(new DwfProduction.Recipe<>("other",Map.of("metal",100L),"other",1,100));check(pi.count("metal")==18&&engine.progress()==0,"switching recipe cannot lose or refund ingredients");
  var reduced=new DwfBulkStore<String>(10,1);reduced.restore("oldA",40);reduced.restore("oldB",40);check(reduced.total()==80&&reduced.size()==2,"lowered admin limits preserve old stock");check(reduced.insert("oldA",1,false)==0&&reduced.insert("new",1,false)==0,"over-limit insertion blocked without negative counts");check(reduced.extract("oldA",30,false)==30&&reduced.total()==50,"excess remains extractable");
  System.out.println("PASS "+checks+" bulk-storage / transaction / scheduler / production checks");
 }
}
